      '/**\n * @brief Restore the original HC-down row-major lane before its original fold.\n * @param value Original per-pair partial in native column-interleaved lanes.\n * @param lane Original physical lane0..63, with full-wave participation.\n * @return Exact float bits from native lane2*partition+row.\n * @details Preload and dot use lane/2 for K and lane%2 for the row. This\n * inverse moves no arithmetic: the unchanged half32 tree and original lane31\n * and63 writers receive precisely their original row/partition values.\n */\n__device__ __forceinline__ float native_hc_down_original_lane(float value,unsigned lane) {\n    const unsigned source=((lane & 31u) << 1) | (lane >> 5);\n    return __int_as_float(__builtin_amdgcn_ds_bpermute(source << 2,__float_as_int(value)));\n}\n\n// 8 consecutive threads quantize 32 values (4 each) into a q8_1 block with ds = (d, sum), as quantize_q8_1',
