 edit('    // ---- HC down: wave w takes row pairs RPW2*w + j (row 2(.) on lanes 0-31, 2(.)+1 on lanes 32-63) of the tile, one\n    //      q8 block pair per lane and all T tokens (loads unconditional so every wave issues 17 per pair: spare lanes\n    //      reload the last pair)\n#pragma unroll\n    for (int j = 0; j < RPW2; ++j) {\n        const int half_ = lane / 32, p = min(lane >> 1, npk - 1);\n        const int row = rg*RPG + 2*(wave*RPW2 + j) + half_;\n        const int * w = wdn[j];\n        const int qs1 = (clk + 1)*(QB/HC) - kq0; // local q from which the K slice is in the next stream (even)\n#pragma unroll\n        for (int t = 0; t < T; ++t) {\n            const float v = (lane >> 1) < npk ? pair_dot(w, xqk[t][2*p], xqk[t][2*p + 1]) : 0.0f;\n            float p0 = 2*p < qs1 ? v : 0.0f, p1 = 2*p < qs1 ? 0.0f : v;\n            p0 = native_hc_down_original_lane(p0, unsigned(lane));\n            p1 = native_hc_down_original_lane(p1, unsigned(lane));\n            p0 = half32_sum(p0); p1 = half32_sum(p1);\n            if (lane % 32 == 31) {\n                acc_add(&A.lo[t][clk][row], p0);\n                if (qs1 < nqk) { acc_add(&A.lo[t][clk + 1][row], p1); }\n            }\n        }\n    }\n','    // ---- HC down: a wave owns32 adjacent rows at two original K pairs.\n    // Store exact original per-row leaves in the already-retired phase arena.\n    // A padded stride33 gives both row-wide producers and half32 consumers a\n    // bank permutation. All1024 lanes publish, including original+0 tail leaves.\n    static_assert(NT==1024 && RPW2==1 && RPG==32,"row-wide HC-down requires the admitted32-row CTA");\n    constexpr unsigned HC_DOWN_LEAF_WORDS=32u*33u;\n    static_assert(sizeof(arena)>=T*HC_DOWN_LEAF_WORDS*sizeof(float),"HC-down leaves must fit original phase storage");\n#pragma unroll\n    for (int t = 0; t < T; ++t) {\n        const unsigned owned_pair=native_hc_down_pair(unsigned(wave),unsigned(lane));\n        const int p=min(int(owned_pair),npk-1);\n        const float v=owned_pair<unsigned(npk) ? pair_dot(wdn[0],xqk[t][2*p],xqk[t][2*p+1]) : 0.0f;\n        reinterpret_cast<float*>(arena)[unsigned(t)*HC_DOWN_LEAF_WORDS+\n            native_hc_down_leaf(native_hc_down_row(unsigned(lane)),owned_pair)]=v;\n    }\n    // Local LDS publication only: no global consumer depends on these leaves.\n    // All waves participate, including those with no numerical K pair.\n    lds_sync();\n#pragma unroll\n    for (int t = 0; t < T; ++t) {\n        // Reconstruct ORIGINAL half32 leaf ownership before its unchanged tree:\n        // physical half-wave selects the row, physical lane%32 selects K pair.\n        const int half_=lane/32,p=min(lane%32,npk-1);\n        const int row=rg*RPG+2*wave+half_;\n        const int qs1=(clk+1)*(QB/HC)-kq0;\n        const float v=reinterpret_cast<const float*>(arena)[unsigned(t)*HC_DOWN_LEAF_WORDS+\n            native_hc_down_leaf(unsigned(2*wave+half_),unsigned(lane%32))];\n        float p0=2*p<qs1 ? v : 0.0f,p1=2*p<qs1 ? 0.0f : v;\n        p0=half32_sum(p0); p1=half32_sum(p1);\n        if (lane%32==31) {\n            acc_add(&A.lo[t][clk][row],p0);\n            if (qs1<nqk) { acc_add(&A.lo[t][clk+1][row],p1); }\n        }\n    }\n    // The following original all-wave join/grid publication retires every leaf\n    // read before HC-up part[] reuses this same arena. Token planes are disjoint.\n','phase-local exact leaves restore original half32 trees')
